<section class="page-heading"><div><p class="eyebrow">MA GARDE-ROBE</p><h1><?= $editing ? 'Modifier la pièce' : 'Ajouter une pièce' ?></h1><p class="subheading">Les champs avec * sont nécessaires pour enregistrer.</p></div><a class="button secondary back-button" href="<?= e($editing ? url('clothes-show',['id'=>$id]) : url('clothes')) ?>">← Retour</a></section>
<?php foreach ($errors as $error): ?><div class="form-error wide-error"><?= e($error) ?></div><?php endforeach; ?>
<form method="post" enctype="multipart/form-data" class="edit-form"><?= csrf_field() ?><div class="form-panel"><div class="panel-heading"><span class="panel-index">01</span><div><h2>Informations principales</h2><p>Identifiez cette pièce dans votre collection.</p></div></div><div class="form-row"><label>Nom de la pièce *<input name="name" maxlength="160" required placeholder="Ex. Chemise en lin blanche" value="<?= e($values['name'] ?? '') ?>"></label><label>Libellé principal *<select name="label_id" required><option value="">Choisir un libellé</option><?php foreach ($labels as $label): ?><option value="<?= e($label['id']) ?>" <?= (string)($values['label_id'] ?? '') === (string)$label['id'] ? 'selected' : '' ?>><?= e($label['name']) ?></option><?php endforeach; ?></select></label><label>Catégorie *<select name="category_id" required data-category-select><option value="">Choisir une catégorie</option><?php foreach ($categories as $category): ?><option value="<?= e($category['id']) ?>" data-label-id="<?= e($category['label_id']) ?>" <?= (string)($values['category_id'] ?? '') === (string)$category['id'] ? 'selected' : '' ?>><?= e($category['name']) ?></option><?php endforeach; ?></select></label></div><label>Sous-catégorie (facultatif)<select name="subcategory_id" data-subcategory-select><option value="">Aucune</option><?php foreach ($subcategories as $subcategory): ?><option value="<?= e($subcategory['id']) ?>" data-category-id="<?= e($subcategory['category_id']) ?>" <?= (string)($values['subcategory_id'] ?? '') === (string)$subcategory['id'] ? 'selected' : '' ?>><?= e($subcategory['name']) ?></option><?php endforeach; ?></select></label><label>Description<textarea name="description" rows="3" placeholder="Quelques détails utiles…"><?= e($values['description'] ?? '') ?></textarea></label><div class="form-row"><label>Couleur principale<input name="color" value="<?= e($values['color'] ?? '') ?>" placeholder="Ex. Bleu marine"></label><label>Marque<input name="brand" value="<?= e($values['brand'] ?? '') ?>" placeholder="Ex. COS"></label></div><div class="form-row"><label>Taille<input name="size" value="<?= e($values['size'] ?? '') ?>" placeholder="Ex. M, 40"></label><label>État<select name="status"><?php foreach (['available'=>'Disponible','laundry'=>'Au lavage','repair'=>'À réparer','unavailable'=>'Indisponible','archived'=>'Archivé'] as $key=>$label): ?><option value="<?= e($key) ?>" <?= ($values['status'] ?? 'available') === $key ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></label></div></div>
<div class="form-panel"><div class="panel-heading"><span class="panel-index">02</span><div><h2>Photo et détails</h2><p>La photo aide à visualiser votre garde-robe.</p></div></div><?php if (!empty($values['image_path'])): ?><div class="current-photo"><img src="<?= e(APP_BASE_URL . '/' . $values['image_path']) ?>" alt="Photo actuelle"><span>Photo actuelle</span></div><?php endif; ?><label class="upload-box">Photo principale <?= $editing ? '(laisser vide pour conserver)' : '*' ?><input type="file" name="photo" accept="image/jpeg,image/png,image/webp" <?= $editing ? '' : 'required' ?> data-image-preview><small>JPG, PNG ou WEBP · 5 Mo maximum</small><img class="upload-preview" alt="Aperçu de la photo" hidden></label><label class="upload-box">Photos supplementaires<input type="file" name="gallery[]" multiple accept="image/jpeg,image/png,image/webp"><small>Plusieurs photos possibles, 5 Mo maximum chacune.</small></label><div class="form-row"><label>Prix d’achat<input type="number" name="purchase_price" min="0" step="0.01" value="<?= e($values['purchase_price'] ?? '') ?>" placeholder="0,00"></label><label>Devise<input name="currency" maxlength="3" value="<?= e($values['currency'] ?? 'USD') ?>" placeholder="USD"></label></div><div class="form-row"><label>Saison<input name="season" value="<?= e($values['season'] ?? '') ?>" placeholder="Ex. Toute l’année"></label><label>Style<input name="style" value="<?= e($values['style'] ?? '') ?>" placeholder="Ex. Minimaliste"></label></div><label>Niveau de formalite<select name="formality"><option value="">Non precise</option><?php foreach(['casual'=>'Decontracte','smart_casual'=>'Decontracte chic','formal'=>'Formel','black_tie'=>'Tenue de soiree'] as $key=>$value): ?><option value="<?= e($key) ?>" <?= ($values['formality']??'')===$key?'selected':'' ?>><?= e($value) ?></option><?php endforeach; ?></select></label><label>Occasion<input name="occasion" value="<?= e($values['occasion'] ?? '') ?>" placeholder="Ex. Travail, quotidien"></label>